    // Compute the size taken up by the index' DB
    stats.database_size = index.env.len()?;

    // Compute the size taken by the used pages of the index' DB
    stats.used_database_size = index.env.used_size()?;

    // Compute the number of embeddings and embedded documents
    if index.vector_store.is_some() {
        let vector_store = index.vector_store.as_ref().unwrap();
        stats.number_of_embeddings = Some(vector_store.number_of_embeddings());
        stats.number_of_embedded_documents = Some(vector_store.number_of_embedded_documents());
    }

    // Compute the field distribution
    for (field_name, field_count) in index.main.field_distribution(rtxn)? {
        stats.field_distribution.insert(field_name.to_string(), field_count);
    }

    // Compute the creation and update dates
    stats.created_at = index.created_at;
    stats.updated_at = index.updated_at;

    Ok(stats)
}
