            // so we need to check that we are not iterating over the next field id
            if key.field_id != self.field_id {
                return Ok(ControlFlow::Break(()));
            }
            let docids_in_common = CboRoaringBitmapCodec::intersection_with_serialized(
                value.bitmap_bytes,
                candidates,
