        &mut self,
        candidates: &RoaringBitmap,
        starting_bound: Option<&[u8]>,
        group_size: usize,
    ) -> Result<ControlFlow<()>> {
        let first_facet_value = get_first_facet_value(self.rtxn, self.db, self.field_id)?;
