pub(crate) fn get_highest_level<'t, DC>(
    txn: &'t RoTxn<'t>,
    db: heed::Database<FacetGroupKeyCodec<BytesRefCodec>, DC>,
    field_id: u16,
) -> heed::Result<u8> {
